-- Career entries are generated by clan-membership history, not profile edits.
-- Keep authenticated reads and the existing SECURITY DEFINER membership
-- triggers, but remove every client write path into the derived totals.
drop policy if exists "Users can insert their own career entries"
  on public.profile_career_entries;
drop policy if exists "Users can update their own career entries"
  on public.profile_career_entries;
drop policy if exists "Users can delete their own career entries"
  on public.profile_career_entries;

revoke insert, update, delete, truncate, references, trigger
  on public.profile_career_entries from public, anon, authenticated;

-- Table revocation does not revoke an independently granted column privilege.
-- Revoke those too, so future column-specific grants cannot leave a bypass.
do $migration$
declare columns_to_use text;
begin
  select string_agg(quote_ident(attname), ', ' order by attnum)
    into columns_to_use
  from pg_attribute
  where attrelid='public.profile_career_entries'::regclass
    and attnum>0 and not attisdropped;
  execute format('revoke insert (%1$s), update (%1$s), references (%1$s)
    on public.profile_career_entries from public, anon, authenticated',columns_to_use);
end;
$migration$;

comment on table public.profile_career_entries is
  'Server-managed clan membership career history. Players may read career entries but cannot create, edit or delete them.';
notify pgrst,'reload schema';
